#pragma once

// Included by LearnCatalog.hpp after LearnEntry and Lang are defined.
// New module help is kept outside the historical 800-entry tables.
#include <array>
#include <vector>

namespace rasgo::panel::detail {

inline std::size_t reactiveLanguage(Lang language) {
    return language == Lang::en ? 1 : language == Lang::fr ? 2 : language == Lang::es ? 3 : 0;
}

struct ReactiveHelp {
    const char* module;
    const char* bind;
    std::array<LearnEntry, 4> text;
};

inline const LearnEntry* lookupReactiveLearn(const std::string& module,
                                             const std::string& bind, Lang lang) {
    const auto row = [](const char* m, const char* b, const char* pt, const char* en,
                        const char* fr, const char* es) {
        return ReactiveHelp{m, b, {{{pt, "", ""}, {en, "", ""}, {fr, "", ""}, {es, "", ""}}}};
    };
    static const std::vector<ReactiveHelp> table = {
        row("LISTEN", "", "Escuta em três bandas: níveis e ataques viram CV. THRU conserva o áudio. LOW/MID/HIGH são regiões de frequência, não instrumentos isolados. Experimente L-HIT no CLK do PHRASE e HIGH num filtro.",
            "Three listening bands: levels and attacks become CV. THRU preserves audio. LOW/MID/HIGH are frequency regions, not isolated instruments. Try L-HIT into PHRASE CLK and HIGH into a filter.",
            "Écoute en trois bandes : niveaux et attaques deviennent CV. THRU conserve l'audio. LOW/MID/HIGH sont des régions de fréquence, pas des instruments isolés. Essayez L-HIT vers CLK du PHRASE et HIGH vers un filtre.",
            "Escucha en tres bandas: niveles y ataques se vuelven CV. THRU conserva el audio. LOW/MID/HIGH son regiones de frecuencia, no instrumentos aislados. Prueba L-HIT en CLK del PHRASE y HIGH en un filtro."),
        row("LISTEN", "low_cut", "Corte grave/médio: 60–800 Hz. Mover o corte suspende ataques por 50 ms para evitar disparos do próprio ajuste.", "Low/mid split: 60–800 Hz. Moving it inhibits attacks for 50 ms to avoid adjustment transients.", "Séparation grave/médium : 60–800 Hz. Un changement suspend les attaques pendant 50 ms.", "Corte grave/medio: 60–800 Hz. Al moverlo se inhiben ataques durante 50 ms."),
        row("LISTEN", "high_cut", "Corte médio/agudo: 1–8 kHz, limitado pela taxa de amostragem.", "Mid/high split: 1–8 kHz, limited by sample rate.", "Séparation médium/aigu : 1–8 kHz, limitée par la fréquence d'échantillonnage.", "Corte medio/agudo: 1–8 kHz, limitado por la frecuencia de muestreo."),
        row("LISTEN", "response", "Suaviza os níveis: ataque de 1–81 ms e queda de 40–1240 ms. Não altera o detector de ataques.", "Level smoothing: 1–81 ms attack, 40–1240 ms release. Does not change attack detection.", "Lissage des niveaux : attaque 1–81 ms, relâchement 40–1240 ms. Détection des attaques indépendante.", "Suaviza niveles: ataque 1–81 ms, caída 40–1240 ms. No cambia la detección de ataques."),
        row("LISTEN", "sens", "Sensibilidade dos ataques: maior detecta contrastes menores entre envelope rápido e lento.", "Attack sensitivity: higher detects smaller fast/slow envelope contrasts.", "Sensibilité des attaques : plus élevée détecte de plus petits contrastes d'enveloppe.", "Sensibilidad de ataques: más alta detecta contrastes menores entre envolventes."),
        row("LISTEN", "floor", "Piso de amplitude para disparar, −72 a −18 dBFS. Não é ganho nem normalização.", "Attack amplitude floor, −72 to −18 dBFS. Not gain or normalisation.", "Seuil d'amplitude des attaques, −72 à −18 dBFS. Ce n'est pas un gain.", "Umbral de amplitud de ataques, −72 a −18 dBFS. No es ganancia."),
        row("LISTEN", "rearm", "Intervalo mínimo entre ataques da mesma banda: 20–250 ms.", "Minimum interval between attacks in the same band: 20–250 ms.", "Intervalle minimal entre attaques d'une même bande : 20–250 ms.", "Intervalo mínimo entre ataques de la misma banda: 20–250 ms."),
        row("LISTEN", "in:in", "Áudio a escutar. Os canais contribuem por magnitude; estéreo em oposição não desaparece da análise.", "Audio to listen to. Channels contribute magnitudes; opposite-phase stereo does not cancel analysis.", "Audio à écouter. Les canaux contribuent par amplitude ; la stéréo en opposition ne s'annule pas dans l'analyse.", "Audio que escuchar. Se combinan magnitudes; estéreo en oposición no cancela el análisis."),
        row("LISTEN", "out:thru", "Áudio de entrada preservado por canal, sem atraso adicional. Valores não finitos viram zero.", "Input audio preserved per channel, with no added delay. Non-finite samples become zero.", "Audio d'entrée conservé par canal, sans délai ajouté. Les valeurs non finies deviennent zéro.", "Audio de entrada conservado por canal, sin retardo adicional. Valores no finitos pasan a cero."),
        row("LISTEN", "out:low", "Envelope grave, 0–1, sem ganho automático. Use em VCA ou modulação de parâmetro.", "Low-band envelope, 0–1, no automatic gain. Use for a VCA or parameter modulation.", "Enveloppe grave, 0–1, sans gain automatique. Vers un VCA ou un paramètre.", "Envolvente grave, 0–1, sin ganancia automática. Para VCA o modulación."),
        row("LISTEN", "out:mid", "Envelope médio, 0–1. Não é áudio da banda.", "Mid-band envelope, 0–1. Not band audio.", "Enveloppe médium, 0–1. Ce n'est pas l'audio de la bande.", "Envolvente media, 0–1. No es audio de banda."),
        row("LISTEN", "out:high", "Envelope agudo, 0–1. Pratos e ruído podem orientar o timbre de outra voz.", "High-band envelope, 0–1. Cymbals and noise can steer another voice's timbre.", "Enveloppe aiguë, 0–1. Cymbales et bruit peuvent guider le timbre d'une autre voix.", "Envolvente aguda, 0–1. Platos y ruido pueden dirigir el timbre de otra voz."),
        row("LISTEN", "out:low_hit", "Pulso grave de 5 ms por ataque detectado. Use em CLK/GATE; não estima BPM.", "5 ms low-band attack pulse. Use for CLK/GATE; does not estimate BPM.", "Impulsion grave de 5 ms par attaque. Vers CLK/GATE ; n'estime pas le BPM.", "Pulso grave de 5 ms por ataque. Para CLK/GATE; no estima BPM."),
        row("LISTEN", "out:mid_hit", "Pulso de 5 ms por ataque nos médios.", "5 ms mid-band attack pulse.", "Impulsion de 5 ms par attaque dans le médium.", "Pulso de 5 ms por ataque en medios."),
        row("LISTEN", "out:high_hit", "Pulso de 5 ms por ataque nos agudos. REARM limita redobros detectados.", "5 ms high-band attack pulse. REARM limits repeated detections.", "Impulsion de 5 ms par attaque aiguë. REARM limite les détections répétées.", "Pulso de 5 ms por ataque agudo. REARM limita repeticiones."),
        row("PHRASE", "", "Motivo de 2–16 passos tocado por CLK externo. Mantém um desenho, cria variantes e retorna à altura de apoio. Ligue PITCH ao QUANTIZER com RANGE=1 para escolher a escala, ou diretamente a uma voz em 1 V/oct.",
            "A 2–16 step motif played by external CLK. Retains a contour, varies it and returns to an anchor pitch. Send PITCH to QUANTIZER with RANGE=1 to choose a scale, or directly to a 1 V/oct voice.",
            "Motif de 2–16 pas joué par CLK externe. Garde un contour, le varie et revient à une hauteur d'appui. PITCH vers QUANTIZER avec RANGE=1 pour choisir l'échelle, ou directement vers une voix 1 V/oct.",
            "Motivo de 2–16 pasos tocado por CLK externo. Conserva un dibujo, crea variantes y vuelve a la altura de apoyo. PITCH a QUANTIZER con RANGE=1 para elegir escala, o directo a una voz 1 V/oct."),
        row("PHRASE", "length", "Comprimento do motivo: 2–16 pulsos. END marca o último passo; o próximo começa outra frase.", "Motif length: 2–16 pulses. END marks the last step; the next starts another phrase.", "Longueur du motif : 2–16 impulsions. END marque le dernier pas.", "Longitud del motivo: 2–16 pulsos. END marca el último paso."),
        row("PHRASE", "span", "Âmbito máximo em torno do apoio, 1–36 semitons. Não escolhe escala.", "Maximum span around the anchor, 1–36 semitones. Does not choose a scale.", "Ambitus maximal autour de l'appui, 1–36 demi-tons. Ne choisit pas l'échelle.", "Ámbito máximo alrededor del apoyo, 1–36 semitonos. No elige escala."),
        row("PHRASE", "direction", "−1 desce; 0 conserva o contorno do motivo; +1 sobe. CAD pode fechar no apoio.", "−1 descends; 0 keeps the motif contour; +1 ascends. CAD may close at the anchor.", "−1 descend ; 0 garde le contour du motif ; +1 monte. CAD peut conclure sur l'appui.", "−1 baja; 0 conserva el contorno del motivo; +1 sube. CAD puede cerrar en el apoyo."),
        row("PHRASE", "variation", "Varia cada interpretação sem sobrescrever o motivo. Zero repete as mesmas alturas com os outros controles fixos.", "Varies each performance without overwriting the motif. Zero repeats pitches when other controls stay fixed.", "Varie l'interprétation sans réécrire le motif. Zéro répète les hauteurs si les autres commandes restent fixes.", "Varía la interpretación sin reescribir el motivo. Cero repite alturas con los demás controles fijos."),
        row("PHRASE", "space", "Probabilidade de pausa entre começo e final. O primeiro e o último passo sempre articulam.", "Rest probability between beginning and ending. First and last steps always articulate.", "Probabilité de silence entre début et fin. Premier et dernier pas toujours articulés.", "Probabilidad de silencio entre inicio y final. Primer y último paso siempre articulan."),
        row("PHRASE", "cadence", "Chance de retornar ao apoio no final. Um gesto em RET solicita o retorno no próximo CLK.", "Chance to return to the anchor at the end. A RET gesture requests return on the next CLK.", "Probabilité de revenir à l'appui à la fin. RET demande ce retour au prochain CLK.", "Probabilidad de volver al apoyo al final. RET solicita el retorno en el próximo CLK."),
        row("PHRASE", "gate_ms", "Duração articulada: 5–400 ms. Um novo passo rearticula mesmo se o gate anterior ainda estiver alto.", "Articulation length: 5–400 ms. A new step retriggers even while the previous gate is high.", "Durée d'articulation : 5–400 ms. Un nouveau pas réarticule même si le gate précédent est haut.", "Duración de articulación: 5–400 ms. Cada paso rearticula aunque el gate previo siga alto."),
        row("PHRASE", "seed", "Identidade numérica do motivo. Alterar recria o desenho e volta ao primeiro passo; nenhum arquivo de áudio é usado.", "Numerical motif identity. Changing it rebuilds the contour and returns to step one; uses no audio files.", "Identité numérique du motif. La changer recrée le contour et revient au premier pas ; aucun fichier audio.", "Identidad numérica del motivo. Cambiarla recrea el dibujo y vuelve al primer paso; no usa archivos de audio."),
        row("PHRASE", "in:pitch", "Apoio em 1 V/oct, capturado no primeiro passo de cada frase. Sem cabo: 0 V.", "Anchor in 1 V/oct, sampled on the first step of each phrase. Unpatched: 0 V.", "Appui en 1 V/oct, capturé au premier pas de chaque phrase. Sans câble : 0 V.", "Apoyo en 1 V/oct, capturado en el primer paso de cada frase. Sin cable: 0 V."),
        row("PHRASE", "in:clock", "Cada borda ascendente toca um passo. Experimente L-HIT do LISTEN ou CLOCK. Sem CLK não avança.", "Each rising edge plays one step. Try LISTEN L-HIT or CLOCK. Without CLK it does not advance.", "Chaque front montant joue un pas. Essayez L-HIT du LISTEN ou CLOCK. Sans CLK, pas d'avance.", "Cada flanco ascendente toca un paso. Prueba L-HIT del LISTEN o CLOCK. Sin CLK no avanza."),
        row("PHRASE", "in:reset", "Recomeça a sequência determinística e silencia a articulação. Espera o próximo CLK.", "Restarts the deterministic sequence and silences articulation. Waits for the next CLK.", "Recommence la séquence déterministe et coupe l'articulation. Attend le prochain CLK.", "Reinicia la secuencia determinista y silencia la articulación. Espera al próximo CLK."),
        row("PHRASE", "in:stim", "Intensidade 0–1: acentua a resposta, reduz pausas e amplia a variação ajustada em VAR. Sem cabo: 1.", "Intensity 0–1: increases accent, reduces rests and opens the variation set by VAR. Unpatched: 1.", "Intensité 0–1 : accentue la réponse, réduit les silences et ouvre la variation VAR. Sans câble : 1.", "Intensidad 0–1: aumenta acento, reduce pausas y amplía la variación VAR. Sin cable: 1."),
        row("PHRASE", "in:return", "Borda ascendente pede conclusão no próximo passo: volta ao apoio, emite END e reinicia o motivo.", "Rising edge requests closure on the next step: anchor pitch, END pulse, then restart.", "Un front montant demande une conclusion au prochain pas : appui, END, puis reprise.", "Un flanco ascendente pide conclusión en el próximo paso: apoyo, END y reinicio."),
        row("PHRASE", "out:pitch", "Altura mantida em 1 V/oct. QUANTIZER CV com RANGE=1 ou OSC PITCH. Nas pausas mantém a altura anterior.", "Held pitch in 1 V/oct. QUANTIZER CV with RANGE=1 or OSC PITCH. Holds the previous pitch during rests.", "Hauteur tenue en 1 V/oct. QUANTIZER CV avec RANGE=1 ou OSC PITCH. Conservée pendant les silences.", "Altura mantenida en 1 V/oct. QUANTIZER CV con RANGE=1 u OSC PITCH. Se mantiene en las pausas."),
        row("PHRASE", "out:gate", "Articulação 0/1. Ligue ao gate de ENVELOPE/LPG; começa uma amostra após o CLK para separar notas rápidas.", "Articulation 0/1. Patch to ENVELOPE/LPG gate; begins one sample after CLK to separate fast notes.", "Articulation 0/1. Vers le gate ENVELOPE/LPG ; commence une période d'échantillon après CLK.", "Articulación 0/1. Al gate de ENVELOPE/LPG; empieza una muestra después de CLK para separar notas."),
        row("PHRASE", "out:accent", "Acento 0–1 para VCA ou modulação de timbre. Começo, meio e final recebem pesos diferentes.", "Accent 0–1 for a VCA or timbre modulation. Beginning, middle and ending have different weights.", "Accent 0–1 pour VCA ou timbre. Début, milieu et fin ont des poids différents.", "Acento 0–1 para VCA o timbre. Inicio, medio y final tienen pesos distintos."),
        row("PHRASE", "out:end", "Pulso de 5 ms no passo final ou retorno solicitado. Pode estimular outro processo ou frase.", "5 ms pulse on the ending step or requested return. Can stimulate another process or phrase.", "Impulsion de 5 ms au pas final ou retour demandé. Peut stimuler un autre processus.", "Pulso de 5 ms en el paso final o retorno solicitado. Puede estimular otro proceso."),
        row("PHRASE", "out:phase", "Posição 0–1 dentro da frase. Mantida entre pulsos; use para conduzir uma transformação lenta.", "Position 0–1 within the phrase, held between pulses. Use to steer a slow transformation.", "Position 0–1 dans la phrase, tenue entre impulsions. Pour guider une transformation lente.", "Posición 0–1 dentro de la frase, mantenida entre pulsos. Para dirigir una transformación lenta.")
    };
    for (const auto& entry : table)
        if (module == entry.module && bind == entry.bind)
            return &entry.text[reactiveLanguage(lang)];
    return nullptr;
}

} // namespace rasgo::panel::detail
